cat >> src/components.tsx <<'EOF'

const dialogButtons = {
  cancel: 'min-h-10 rounded-md border border-slate-300 bg-white px-4 py-2 text-sm font-medium text-slate-700 hover:bg-slate-100',
  primary: 'min-h-10 rounded-md bg-indigo-600 px-4 py-2 text-sm font-semibold text-white hover:bg-indigo-700',
}

export function BoardNameForm({ initial, submitLabel, onSubmit, onCancel }: {
  initial: string
  submitLabel: string
  onSubmit: (name: string) => void
  onCancel: () => void
}) {
  const [name, setName] = useState(initial)
  const [touched, setTouched] = useState(false)
  const blank = name.trim() === ''
  // A blank name is only an error when renaming; creating falls back to "Board N".
  const required = initial !== ''
  return (
    <form
      noValidate
      onSubmit={(e) => {
        e.preventDefault()
        setTouched(true)
        if (!(required && blank)) onSubmit(name)
      }}
      className="space-y-3"
    >
      <label className="block text-sm font-medium text-slate-700">
        Board name
        <input
          className={field}
          value={name}
          maxLength={60}
          placeholder={required ? undefined : 'e.g. Work, Home, Side project'}
          onChange={(e) => setName(e.target.value)}
          aria-invalid={touched && required && blank}
        />
        {touched && required && blank && <span role="alert" className="mt-1 block text-sm text-red-700">Name is required.</span>}
      </label>
      <div className="flex justify-end gap-2 pt-2">
        <button type="button" onClick={onCancel} className={dialogButtons.cancel}>Cancel</button>
        <button type="submit" className={dialogButtons.primary}>{submitLabel}</button>
      </div>
    </form>
  )
}

export function MoveToBoardForm({ boards, defaultColumn, onSubmit, onCancel }: {
  boards: { id: string; name: string }[]
  defaultColumn: ColumnId
  onSubmit: (boardId: string, column: ColumnId) => void
  onCancel: () => void
}) {
  const [boardId, setBoardId] = useState(boards[0]?.id ?? '')
  const [column, setColumn] = useState<ColumnId>(defaultColumn)
  return (
    <form
      onSubmit={(e) => {
        e.preventDefault()
        if (boardId) onSubmit(boardId, column)
      }}
      className="space-y-3"
    >
      <label className="block text-sm font-medium text-slate-700">
        Destination board
        <select className={field} value={boardId} onChange={(e) => setBoardId(e.target.value)}>
          {boards.map((b) => <option key={b.id} value={b.id}>{b.name}</option>)}
        </select>
      </label>
      <label className="block text-sm font-medium text-slate-700">
        Column
        <select className={field} value={column} onChange={(e) => setColumn(e.target.value as ColumnId)}>
          {COLUMN_IDS.map((c) => <option key={c} value={c}>{COLUMN_TITLES[c]}</option>)}
        </select>
      </label>
      <div className="flex justify-end gap-2 pt-2">
        <button type="button" onClick={onCancel} className={dialogButtons.cancel}>Cancel</button>
        <button type="submit" className={dialogButtons.primary}>Move card</button>
      </div>
    </form>
  )
}
EOF
